  - intros p _. apply lap_0RB0LC_1LC1RB_0RD1LA_1LA1LA.
  - intros t Ht p _. apply fire_0RB0LC_1LC1RB_0RD1LA_1LA1LA. exact Ht.
  - exact wit_0RB0LC_1LC1RB_0RD1LA_1LA1LA.
  - apply qcleb_QC_02. reflexivity.
Qed.

Theorem qhtr_0RB0LC_1LC1RB_0RD1LA_1LA1LA : NonHalt tm_0RB0LC_1LC1RB_0RD1LA_1LA1LA /\ QHBoundTr 32779478 tm_0RB0LC_1LC1RB_0RD1LA_1LA1LA /\ QuasiHaltsTr tm_0RB0LC_1LC1RB_0RD1LA_1LA1LA.
