(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_0RB0LC_1LC1RB_0RD1LA_1LA1LD : forall j, lift (cden [] [] j BB1_0RB0LC_1LC1RB_0RD1LA_1LA1LD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LC_1LC1RB_0RD1LA_1LA1LD = (StD, (rep [S1;S0] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_0RB0LC_1LC1RB_0RD1LA_1LA1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB0LC_1LC1RB_0RD1LA_1LA1LD. rewrite epow2_0RB0LC_1LC1RB_0RD1LA_1LA1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0LC_1LC1RB_0RD1LA_1LA1LD. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB0LC_1LC1RB_0RD1LA_1LA1LD : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB0LC_1LC1RB_0RD1LA_1LA1LD.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB0LC_1LC1RB_0RD1LA_1LA1LD, cden, BE0_0RB0LC_1LC1RB_0RD1LA_1LA1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LC_1LC1RB_0RD1LA_1LA1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB0LC_1LC1RB_0RD1LA_1LA1LD p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LC_1LC1RB_0RD1LA_1LA1LD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_1LC1RB_0RD1LA_1LA1LD p (pow2 j)).
  - exists (4 * j + 7), (cden [] [] j BB1_0RB0LC_1LC1RB_0RD1LA_1LA1LD).
    split; [lia|]. split; [| exact (gbo_0RB0LC_1LC1RB_0RD1LA_1LA1LD j)].
    rewrite (gso_0RB0LC_1LC1RB_0RD1LA_1LA1LD p j E).
    exact (srun_sound tm true true chb_0RB0LC_1LC1RB_0RD1LA_1LA1LD B0_0RB0LC_1LC1RB_0RD1LA_1LA1LD BB1_0RB0LC_1LC1RB_0RD1LA_1LA1LD 4 7
             run_boot_0RB0LC_1LC1RB_0RD1LA_1LA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 9), (cden [] [] j B1_0RB0LC_1LC1RB_0RD1LA_1LA1LD).
    split; [| exact (geo_0RB0LC_1LC1RB_0RD1LA_1LA1LD p j E)].
    rewrite (gxi_0RB0LC_1LC1RB_0RD1LA_1LA1LD j).
    exact (srun_sound tm true true che_0RB0LC_1LC1RB_0RD1LA_1LA1LD BE0_0RB0LC_1LC1RB_0RD1LA_1LA1LD B1_0RB0LC_1LC1RB_0RD1LA_1LA1LD 4 9
             run_exit_0RB0LC_1LC1RB_0RD1LA_1LA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_0RD1LA_1LA1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RB_0RD1LA_1LA1LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_1LC1RB_0RD1LA_1LA1LD p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB0LC_1LC1RB_0RD1LA_1LA1LD : stepn tmm_0RB0LC_1LC1RB_0RD1LA_1LA1LD 5 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_0RB0LC_1LC1RB_0RD1LA_1LA1LD 5 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_0RB0LC_1LC1RB_0RD1LA_1LA1LD 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_0RB0LC_1LC1RB_0RD1LA_1LA1LD : existsb (fun tg => cfires tmm_0RB0LC_1LC1RB_0RD1LA_1LA1LD c0 5 tg) pins_0RB0LC_1LC1RB_0RD1LA_1LA1LD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_1LC1RB_0RD1LA_1LA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1LC1RB_0RD1LA_1LA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1LC1RB_0RD1LA_1LA1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1LC1RB_0RD1LA_1LA1LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1LC1RB_0RD1LA_1LA1LD : forall t, ~ In t pins_0RB0LC_1LC1RB_0RD1LA_1LA1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LC_1LC1RB_0RD1LA_1LA1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA1LD
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA1LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA1LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA1LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA1LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA1LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0LC_1LC1RB_0RD1LA_1LA1LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 2]).
    vm_compute; reflexivity.
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtrm_0RB0LC_1LC1RB_0RD1LA_1LA1LD : NonHalt tmm_0RB0LC_1LC1RB_0RD1LA_1LA1LD /\ QHBoundTr 32779478 tmm_0RB0LC_1LC1RB_0RD1LA_1LA1LD /\ QuasiHaltsTr tmm_0RB0LC_1LC1RB_0RD1LA_1LA1LD.
