  apply (lap_qh_stage tmm_0RB0LC_1LC1RB_0RD1LA_1LA1LD pins_0RB0LC_1LC1RB_0RD1LA_1LA1LD Cc 1 5 32779478).
  - exact bootq_0RB0LC_1LC1RB_0RD1LA_1LA1LD.
  - intros p _. apply lap_0RB0LC_1LC1RB_0RD1LA_1LA1LD.
  - intros t Ht p _. apply fire_0RB0LC_1LC1RB_0RD1LA_1LA1LD. exact Ht.
  - exact wit_0RB0LC_1LC1RB_0RD1LA_1LA1LD.
  - apply qcleb_QC_02. reflexivity.
Qed.

Theorem qhtr_0RB0LC_1LC1RB_0RD1LA_1LA1LD : NonHalt tm_0RB0LC_1LC1RB_0RD1LA_1LA1LD /\ QHBoundTr 32779478 tm_0RB0LC_1LC1RB_0RD1LA_1LA1LD /\ QuasiHaltsTr tm_0RB0LC_1LC1RB_0RD1LA_1LA1LD.
