Theorem qhtr_0RB0LC_1LC1RB_0RD1LA_1LA1RB : NonHalt tm_0RB0LC_1LC1RB_0RD1LA_1LA1RB /\ QHBoundTr 32779478 tm_0RB0LC_1LC1RB_0RD1LA_1LA1RB /\ QuasiHaltsTr tm_0RB0LC_1LC1RB_0RD1LA_1LA1RB.
