  - exists (4 * j + 7), (cden [] [] j BB1_0RB0LC_1LC1RB_0RD1LA_1RA1LA).
    split; [lia|]. split; [| exact (gbo_0RB0LC_1LC1RB_0RD1LA_1RA1LA j)].
    rewrite (gso_0RB0LC_1LC1RB_0RD1LA_1RA1LA p j E).
    exact (srun_sound tm true true chb_0RB0LC_1LC1RB_0RD1LA_1RA1LA B0_0RB0LC_1LC1RB_0RD1LA_1RA1LA BB1_0RB0LC_1LC1RB_0RD1LA_1RA1LA 4 7
             run_boot_0RB0LC_1LC1RB_0RD1LA_1RA1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 15), (cden [] [] j B1_0RB0LC_1LC1RB_0RD1LA_1RA1LA).
