  - exact bootq_0RB0LC_1LC1RB_0RD1LA_1RA1LA.
  - intros p _. apply lap_0RB0LC_1LC1RB_0RD1LA_1RA1LA.
  - intros t Ht p _. apply fire_0RB0LC_1LC1RB_0RD1LA_1RA1LA. exact Ht.
  - exact wit_0RB0LC_1LC1RB_0RD1LA_1RA1LA.
  - apply qcleb_QC_02. reflexivity.
