Theorem qhtr_0RB0LC_1LC1RB_0RD1LA_1RA1LA : NonHalt tm_0RB0LC_1LC1RB_0RD1LA_1RA1LA /\ QHBoundTr 32779478 tm_0RB0LC_1LC1RB_0RD1LA_1RA1LA /\ QuasiHaltsTr tm_0RB0LC_1LC1RB_0RD1LA_1RA1LA.
