    rewrite (gso_0RB0LC_1LC1RB_0RD1LA_1RB0LC p j E).
    exact (srun_sound tm true true chb_0RB0LC_1LC1RB_0RD1LA_1RB0LC B0_0RB0LC_1LC1RB_0RD1LA_1RB0LC BB1_0RB0LC_1LC1RB_0RD1LA_1RB0LC 4 7
             run_boot_0RB0LC_1LC1RB_0RD1LA_1RB0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 7), (cden [] [] j B1_0RB0LC_1LC1RB_0RD1LA_1RB0LC).
    split; [| exact (geo_0RB0LC_1LC1RB_0RD1LA_1RB0LC p j E)].
