(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_0RD1LA_1RB0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
