  - exact bootq_0RB0LC_1LC1RB_0RD1LA_1RB0LD.
  - intros p _. apply lap_0RB0LC_1LC1RB_0RD1LA_1RB0LD.
  - intros t Ht p _. apply fire_0RB0LC_1LC1RB_0RD1LA_1RB0LD. exact Ht.
  - exact wit_0RB0LC_1LC1RB_0RD1LA_1RB0LD.
  - apply qcleb_QC_02. reflexivity.
Qed.

Theorem qhtr_0RB0LC_1LC1RB_0RD1LA_1RB0LD : NonHalt tm_0RB0LC_1LC1RB_0RD1LA_1RB0LD /\ QHBoundTr 32779478 tm_0RB0LC_1LC1RB_0RD1LA_1RB0LD /\ QuasiHaltsTr tm_0RB0LC_1LC1RB_0RD1LA_1RB0LD.
