  - exists (4 * j + 7), (cden [] [] j BB1_0RB0LC_1LC1RB_0RD1LA_1RB0RC).
    split; [lia|]. split; [| exact (gbo_0RB0LC_1LC1RB_0RD1LA_1RB0RC j)].
    rewrite (gso_0RB0LC_1LC1RB_0RD1LA_1RB0RC p j E).
