Theorem qhtr_0RB0LC_1LC1RB_0RD1LA_1RB0RC : NonHalt tm_0RB0LC_1LC1RB_0RD1LA_1RB0RC /\ QHBoundTr 32779478 tm_0RB0LC_1LC1RB_0RD1LA_1RB0RC /\ QuasiHaltsTr tm_0RB0LC_1LC1RB_0RD1LA_1RB0RC.
