Lemma fire_0RB0LC_1LC1RB_0RD1LA_1RB0RD : forall t, ~ In t pins_0RB0LC_1LC1RB_0RD1LA_1RB0RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
