    by exact lapi_0RB0LC_1LC1RB_0RD1LA_1RB1RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LC_1LC1RB_0RD1LA_1RB1RB
