    apply (lap_of_run tm Cc true true cho_0RB0LC_1LC1RB_1RD1LA_0LC1RC B0_0RB0LC_1LC1RB_1RD1LA_0LC1RC B1_0RB0LC_1LC1RB_1RD1LA_0LC1RC 4 9 p j' [] []).
    + exact run_ovf_0RB0LC_1LC1RB_1RD1LA_0LC1RC.
    + reflexivity.
